/**
 * For the given Spark cluster, start a runningApplicationMonitor, and then register a CRD
 * informer to keep track of all CRD updates. The updates are put into the
 * applicationUpdateEventQueue for processing later.
 *
 * @param sparkCluster Spark cluster
 * @param timer timer to set up runningApplicationMonitor
 */
private void start(AppConfig.SparkCluster sparkCluster, Timer timer) {
    logger.info("Creating informer for spark cluster {}, EKS: {}, namespace: {}", sparkCluster.getId(), sparkCluster.getEksCluster(), sparkCluster.getSparkApplicationNamespace());
    KubernetesClient client = KubernetesHelper.getK8sClient(sparkCluster);
    clients.add(client);
    SharedInformerFactory sharedInformerFactory = client.informers();
    informerFactories.add(sharedInformerFactory);
    SharedIndexInformer<SparkApplication> informer = sharedInformerFactory.sharedIndexInformerFor(SparkApplication.class, RESYNC_MILLIS);
    RunningApplicationMonitor runningApplicationMonitor = new RunningApplicationMonitor(sparkCluster, timer, meterRegistry);
    informer.addEventHandler(new ResourceEventHandler<SparkApplication>() {

        @Override
        public void onAdd(SparkApplication sparkApplicationResource) {
        }

        @Override
        public void onUpdate(SparkApplication prevCRDState, SparkApplication newCRDState) {
            int timeoutMillis = 100;
            try {
                boolean added = applicationUpdateEventQueue.offer(new ApplicationUpdateEvent(sparkCluster, prevCRDState, newCRDState, runningApplicationMonitor), timeoutMillis, TimeUnit.MILLISECONDS);
                if (!added) {
                    requestCounters.increment(MONITOR_DROPPED_EVENT);
                    long value = droppedEvents.incrementAndGet();
                    logger.warn("Failed to enqueue application update event due to queue full, application: {}," + " total dropped: {}", prevCRDState.getMetadata().getName(), value);
                }
            } catch (Throwable e) {
                logger.warn("Failed to enqueue application update event", e);
            }
        }

        @Override
        public void onDelete(SparkApplication sparkApplicationResource, boolean deletedFinalStateUnknown) {
        }
    });
    sharedInformerFactory.addSharedInformerEventListener(ex -> logger.warn(String.format("Got exception with informer for spark cluster %s", sparkCluster.getId()), ex));
    logger.info("Starting all registered informers");
    sharedInformerFactory.startAllRegisteredInformers();
}
